function estimateRow(){const opts=db.products.map(p=>'<option value="'+p.id+'">'+esc(productLabel(p))+'</option>').join('');return '<tr class="estimate-line"><td><select class="est-product"><option value="">পণ্য নির্বাচন</option>'+opts+'</select></td><td><input class="est-qty" type="number" min="0.001" step="0.001" value="1" style="width:75px"></td><td><input class="est-price" type="number" min="0" step="0.01" value="0" style="width:95px"></td><td class="est-sum">৳০</td><td><button type="button" class="danger est-remove">×</button></td></tr>'}
function estimateLinesData(){return Array.from(document.querySelectorAll('.estimate-line')).map(r=>{const p=db.products.find(x=>x.id===r.querySelector('.est-product').value),qty=Number(r.querySelector('.est-qty').value||0),price=Number(r.querySelector('.est-price').value||0);return p&&qty>0?{productId:p.id,name:productLabel(p),qty,unit:p.unit,price,total:qty*price}:null}).filter(Boolean)}
function estimateMessage(x){return ['PURCHASE ESTIMATE','মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি','সাপ্লায়ার: '+x.supplier,'তারিখ: '+x.date,'--------------------',...x.lines.map((v,i)=>(i+1)+'. '+v.name+' | '+v.qty+' '+v.unit+' × '+money(v.price)+' = '+money(v.total)),'--------------------','সর্বমোট: '+money(x.total),'নোট: '+(x.note||'দর ও সরবরাহ নিশ্চিত করুন'),'এটি প্রাথমিক Estimate; নিশ্চিত ক্রয় না হওয়া পর্যন্ত স্টক পরিবর্তন হবে না।'].join('\n')}
function refreshEstimate(){let sum=0;document.querySelectorAll('.estimate-line').forEach(r=>{const q=Number(r.querySelector('.est-qty').value||0),p=Number(r.querySelector('.est-price').value||0),v=q*p;sum+=v;r.querySelector('.est-sum').textContent=money(v)});$('estimateTotal').textContent='মোট: '+money(sum)}
function buildEstimate(){const lines=estimateLinesData();if(!lines.length){alert('কমপক্ষে একটি পণ্য, পরিমাণ ও দর দিন');return null}const x={id:id(),estimateNo:'EST-'+Date.now().toString().slice(-8),date:$('estDate').value||date(),supplier:$('estSupplier').value.trim(),phone:$('estPhone').value.trim(),note:$('estNote').value.trim(),lines,total:lines.reduce((n,v)=>n+v.total,0)};db.purchaseEstimates=db.purchaseEstimates||[];db.purchaseEstimates.push(x);save();$('estimateMessage').textContent='Estimate '+x.estimateNo+' সংরক্ষিত হয়েছে। স্টক পরিবর্তন হয়নি।';return x}
function printPurchaseEstimate(x){const w=window.open('','_blank','width=850,height=900');if(!w){alert('প্রিন্টের জন্য পপ-আপ অনুমতি দিন');return}w.document.write('<!doctype html><html lang="bn"><meta charset="utf-8"><title>Purchase Estimate</title><style>body{font:15px system-ui;padding:28px;color:#18251f}h2{text-align:center}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #bbb;padding:9px;text-align:left}.total{text-align:right;font-size:20px;font-weight:bold;margin-top:20px}</style><h2>'+esc(db.settings.name||'মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি')+'</h2><p style="text-align:center">'+esc(db.settings.address||'')+'<br>'+esc(db.settings.phone||'')+'</p><hr><h3>PURCHASE ESTIMATE '+x.estimateNo+'</h3><p>সাপ্লায়ার: '+esc(x.supplier)+'<br>মোবাইল: '+esc(x.phone||'—')+'<br>তারিখ: '+esc(x.date)+'</p><table><thead><tr><th>পণ্য / গ্রেড / মাপ</th><th>পরিমাণ</th><th>একক</th><th>দর</th><th>মোট</th></tr></thead><tbody>'+x.lines.map(v=>'<tr><td>'+esc(v.name)+'</td><td>'+v.qty+'</td><td>'+esc(v.unit)+'</td><td>'+money(v.price)+'</td><td>'+money(v.total)+'</td></tr>').join('')+'</tbody></table><p class="total">সর্বমোট: '+money(x.total)+'</p><p>নোট: '+esc(x.note||'দর ও সরবরাহ নিশ্চিত করুন')+'</p><p>প্রাথমিক Estimate; নিশ্চিত ক্রয় না হওয়া পর্যন্ত স্টক পরিবর্তন হবে না।</p><p style="margin-top:48px">প্রস্তুতকারীর স্বাক্ষর: _____________　সাপ্লায়ারের সম্মতি: _____________</p><button onclick="window.print()">প্রিন্ট / PDF</button></html>');w.document.close();w.focus()}
