$('purchaseForm').onsubmit=e=>{e.preventDefault();let p=db.products.find(x=>x.id===$('buyProduct').value&&x.companyId===$('buyCompany').value),q=+$('buyQty').value,price=+$('buyPrice').value;if(!p||q<=0)return alert('পণ্য ও পরিমাণ ঠিক করুন');p.stock+=q;p.cost=price;db.purchases.push({id:id(),date:date(),companyId:p.companyId,companyName:companyName(p.companyId),productName:productLabel(p),qty:q,total:q*price,supplier:$('buySupplier').value});save();e.target.reset();};
function updateSalePrice(){let p=db.products.find(x=>x.id===$('saleProduct').value);if(!p)return;let u=$('saleUnit').value,m=u==='box'?p.box:u==='bundle'?p.bundle:1;if(u!=='base'&&m<=0){$('saleMessage').textContent='এই পণ্যের জন্য '+u+' conversion সেট করা নেই।';$('salePrice').value=0;return}$('salePrice').value=($('saleType').value==='wholesale'?p.wholesale:p.retail)*m;$('saleMessage').textContent=`প্রতি ${u==='base'?p.unit:u} = ${m} ${p.unit}`;calcTotal()}['saleProduct','saleUnit','saleType'].forEach(x=>$(x).addEventListener('change',updateSalePrice));$('buyCompany').addEventListener('change',refreshCompanyProductOptions);$('saleCompany').addEventListener('change',refreshCompanyProductOptions);['saleQty','salePrice','saleDiscount'].forEach(x=>$(x).addEventListener('input',calcTotal));function calcTotal(){let subtotal=+$('saleQty').value*+$('salePrice').value,discount=Math.min(100,Math.max(0,+$('saleDiscount').value||0)),off=subtotal*discount/100,t=subtotal-off;$('saleTotal').textContent='মোট: '+money(t)+' (ছাড়: '+money(off)+')'}$('saleBarcode').addEventListener('change',()=>{let p=db.products.find(x=>x.barcode===$('saleBarcode').value.trim()||x.sku===$('saleBarcode').value.trim());if(p&&p.companyId===$('saleCompany').value){$('saleProduct').value=p.id;updateSalePrice();$('saleQty').focus()}else if(p){alert('এই পণ্যটি নির্বাচিত কোম্পানির স্টকে নেই। কোম্পানি পরিবর্তন করুন।')}else alert('এই বারকোডের পণ্য পাওয়া যায়নি')});$('saleForm').onsubmit=e=>{e.preventDefault();let p=db.products.find(x=>x.id===$('saleProduct').value&&x.companyId===$('saleCompany').value),qty=+$('saleQty').value,unit=$('saleUnit').value,m=unit==='box'?p?.box:unit==='bundle'?p?.bundle:1;if(!p||qty<=0||m<=0)return alert('পণ্য/পরিমাণ/ইউনিট পরীক্ষা করুন');let baseQty=qty*m,subtotal=qty*+$('salePrice').value,discountPercent=Math.min(100,Math.max(0,+$('saleDiscount').value||0)),discountAmount=subtotal*discountPercent/100,total=subtotal-discountAmount,paid=+$('salePaid').value;if(baseQty>p.stock)return alert('পর্যাপ্ত স্টক নেই। বর্তমান স্টক: '+p.stock+' '+p.unit);if(paid>total)return alert('জমার টাকা মোটের চেয়ে বেশি');p.stock-=baseQty;let customer=db.customers.find(c=>c.id===$('saleCustomer').value);let s={id:id(),companyId:p.companyId,companyName:companyName(p.companyId),invoice:'MBM-'+Date.now().toString().slice(-8),date:date(),customerId:customer?.id||'',customerName:customer?.name||'সাধারণ কাস্টমার',productName:productLabel(p),qty,unit:unit==='base'?p.unit:unit,baseQty,subtotal,discountPercent,discountAmount,total,paid,due:total-paid,costTotal:baseQty*p.cost};db.sales.push(s);save();showInvoice(s);e.target.reset();$('saleQty').value=1;};
