function download(name,data,type='application/json'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},120000)}function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n')}function downloadExcel(name,rows){const escX=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const table='<html><head><meta charset="UTF-8"></head><body><table>'+rows.map((r,i)=>'<tr>'+r.map(v=>'<td'+(i===0?' style="font-weight:bold;background:#d9eaf7"':'')+'>'+escX(v)+'</td>').join('')+'</tr>').join('')+'</table></body></html>';download(name.replace(/\\.(csv|json)$/i,'')+'.xls','\\ufeff'+table,'application/vnd.ms-excel;charset=utf-8')}$('exportSales').onclick=()=>downloadExcel('madina-sales.xls',[['Invoice','Date','Customer','Product','Quantity','Unit','Total','Paid','Due'],...db.sales.map(s=>[s.invoice,s.date,s.customerName,s.productName,s.qty,s.unit,s.total,s.paid,s.due])]);$('exportStock').onclick=()=>downloadExcel('madina-stock.xls',[['Name','SKU','Unit','Stock','Cost','Retail','Wholesale','Barcode'],...db.products.map(p=>[p.name,p.sku,p.unit,p.stock,p.cost,p.retail,p.wholesale,p.barcode])]);
document.addEventListener('click',e=>{const b=e.target.closest('[data-company-file]');if(!b)return;const co=COMPANY_PROFILES.find(c=>c.id===b.dataset.companyFile);if(!co)return;const items=db.products.filter(p=>p.companyId===co.id);const rows=[['পণ্য','SKU','ক্যাটাগরি','সাইজ','ইউনিট','স্টক','ক্রয়মূল্য','খুচরা মূল্য','পাইকারি মূল্য','বারকোড'],...items.map(p=>[p.name,p.sku,p.category,p.size,p.unit,p.stock,p.cost,p.retail,p.wholesale,p.barcode])];const w=window.open('','_blank');if(w){const escV=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');w.document.write('<meta charset="utf-8"><title>'+co.name+' স্টক</title><h2>'+co.name+'</h2><p>মোট পণ্য: '+items.length+'</p><table border="1" cellpadding="6" cellspacing="0"><thead><tr>'+rows[0].map(x=>'<th>'+escV(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(1).map(r=>'<tr>'+r.map(x=>'<td>'+escV(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>');w.document.close()}downloadExcel(co.id+'-stock.xls',rows)});const backup=()=>download('madina-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(db,null,2));$('backupBtn').onclick=backup;$('downloadBackup').onclick=backup;$('exportAll').onclick=backup;$('importBackup').onchange=async e=>{try{let x=JSON.parse(await e.target.files[0].text());if(!x.products||!x.sales)throw 0;if(confirm('বর্তমান ডেটা ব্যাকআপ দিয়ে প্রতিস্থাপন করবেন?')){db=x;save();alert('ব্যাকআপ ইমপোর্ট হয়েছে')}}catch{alert('সঠিক ব্যাকআপ ফাইল নয়')}};$('clearData').onclick=()=>{if(confirm('সতর্কতা: সব ডেটা স্থায়ীভাবে মুছে যাবে। নিশ্চিত?')){db=blank();save()}};$('saveSettings').onclick=()=>{db.settings={name:$('bizName').value,phone:$('bizPhone').value,address:$('bizAddress').value};save();alert('সেটিংস সংরক্ষিত')};
let stream=null,detector=null;$('scanBtn').onclick=async()=>{if(!('BarcodeDetector'in window))return alert('এই ব্রাউজারে সরাসরি বারকোড স্ক্যান সমর্থিত নয়। USB/Bluetooth স্ক্যানার ব্যবহার করুন অথবা বারকোড লিখুন।');try{detector=new BarcodeDetector({formats:['code_128','ean_13','ean_8','upc_a','upc_e','qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('video').srcObject=stream;$('scanner').classList.add('show');scanLoop()}catch(e){alert('ক্যামেরা চালু করা যায়নি। HTTPS এবং ক্যামেরা অনুমতি পরীক্ষা করুন।')}};async function scanLoop(){if(!$('scanner').classList.contains('show'))return;try{let codes=await detector.detect($('video'));if(codes.length){$('saleBarcode').value=codes[0].rawValue;$('saleBarcode').dispatchEvent(new Event('change'));closeScan();return}}catch{}requestAnimationFrame(scanLoop)}function closeScan(){$('scanner').classList.remove('show');if(stream)stream.getTracks().forEach(t=>t.stop());stream=null}$('closeScanner').onclick=closeScan;
document.addEventListener('click',e=>{const b=e.target.closest('[data-staff-history]');if(!b)return;const s=db.staff.find(x=>x.id===b.dataset.staffHistory);if(!s)return;const tx=db.staffPayments.filter(p=>p.staffId===s.id).map(p=>p.date+' • '+p.month+' • '+(p.type==='advance'?'অগ্রিম':'বেতন')+' • '+money(p.amount)).join('\\n')||'কোনো লেনদেন নেই';alert(s.name+' — বেতন '+money(s.salary)+'\\n'+tx)});$('language').onchange=e=>{document.documentElement.lang=e.target.value;alert(e.target.value==='en'?'The interface is not fully translated yet.':'বাংলা ভাষা নির্বাচন করা হয়েছে।')};$('invoiceSize').onchange=e=>{document.body.classList.remove('print-a4','print-thermal80','print-thermal58');document.body.classList.add('print-'+e.target.value)};$('incomePeriod').onchange=updateIncomeReport;['incomeDay','incomeMonth','incomeYear'].forEach(k=>$(k).addEventListener('change',updateIncomeReport));$('exportPeriodReport').onclick=()=>{const r=window.currentIncomeReport;if(!r)return;download('madina-income-report.csv','\\ufeff'+csv([['সময়','বিক্রয়','আদায়','অন্যান্য আয়','ব্যয়'],...r.rows]),'text/csv')};$('printPeriodReport').onclick=()=>{const r=window.currentIncomeReport;if(!r)return;const w=window.open('','_blank');if(!w)return alert('প্রিন্টের জন্য পপ-আপ অনুমতি দিন');w.document.write('<meta charset="utf-8"><title>আয়-ব্যয়ের রিপোর্ট</title><h2>'+esc(db.settings.name||'মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি')+'</h2><h3>'+esc(r.label)+'</h3><table border="1" cellpadding="8"><tr><th>সময়</th><th>বিক্রয়</th><th>আদায়</th><th>অন্যান্য আয়</th><th>ব্যয়</th></tr>'+r.rows.map(x=>'<tr>'+x.map(v=>'<td>'+esc(String(v))+'</td>').join('')+'</tr>').join('')+'</table><script>window.print()<\\/script>');w.document.close()};renderAll();
